      "outputType": "markdown",
      "output": "const P={\nwl:{id:'wheel_l',cfg:'-',c:[-55,35,0],r:35,t:5},\nwr:{id:'wheel_r',cfg:'-',c:[55,35,0],r:35,t:5},\nft:{id:'fork',cfg:'frame',a:[-55,35,0],b:[-48,90,0],t:2},\nhbt:{id:'head_tube',cfg:'frame',a:[-48,90,0],b:[-44,110,0],t:3},\ntt:{id:'top_tube',cfg:'frame',a:[-44,110,0],b:[20,110,0],t:2.5},\ndt:{id:'down_tube',cfg:'frame',a:[-48,90,0],b:[10,55,0],t:3},\nst:{id:'seat_tube',cfg:'frame',a:[20,110,0],b:[10,55,0],t:3},\nblf:{id:'bs_fork',cfg:'frame',a:[10,55,0],b:[55,35,0],t:2.5},\nblu:{id:'bs_link',cfg:'frame',a:[20,110,0],b:[55,35,0],t:2},\nbat0:{id:'bat_std',cfg:'battery',min:[-15,62,0],max:[5,74,7]},\nbat1:{id:'bat_long',cfg:'battery',min:[-22,62,0],max:[5,74,8]},\nseat0:{id:'seat_sport',cfg:'seat',min:[12,112,-5],max:[30,117,5]},\nseat1:{id:'seat_comf',cfg:'seat',min:[10,112,-7],max:[34,118,7]},\nhbl:{id:'handlebar',cfg:'-',a:[-44,110,-15],b:[-44,110,15],t:2.5},\nbkt:{id:'basket',cfg:'basket',min:[-58,72,-14],max:[-42,92,14]}\n};"
